let ps;

function setup() {
	createCanvas(600, 600);
	let s = 75;
	ps = []
	for (let i = 0; i < 125; i++) {
		const x = (i * s + s/2) % width
		const y = ~~((i * s + s/2) / width) * s
		const c = color(random(333), random(111), random(222))
		const t = random("⬡⬢⬣".split(''))
		ps.push({x, y, t, c, s})
	}

	textAlign(CENTER, CENTER)
	textSize(width * 0.1)

	background(0, 0, 12)
}

function draw() {
	background(0, 0, 12)
	for (let p of ps) {
		stroke(p.c);
		text(p.t, p.x, p.y)
	}
}
